css:
:where(.wtyg-map-reproduction_capture){--ink:#0d0f12;--sheet:#14171b;--sheet2:#191d22;--rule:#262b31;--rule2:#1f2328;
  --text:#e6e3dd;--dim:#9aa0a6;--faint:#6c737a;--accent:#8fa9c9;}
:where(.wtyg-map-reproduction_capture) *{box-sizing:border-box;margin:0;padding:0}
:where(.wtyg-map-reproduction_capture),:where(.wtyg-map-reproduction_capture){height:100%;overflow:hidden;background:var(--ink);color:var(--text);
  font-family:"IBM Plex Sans",system-ui,-apple-system,"Segoe UI",sans-serif;font-size:13.5px;line-height:1.45;-webkit-font-smoothing:antialiased}
:where(.wtyg-map-reproduction_capture) :is([data-wtyg-id="rc"],#wtyg-noid-rc){display:flex;height:100%;width:100%;overflow:hidden}
:where(.wtyg-map-reproduction_capture) :is([data-wtyg-id="side"],#wtyg-noid-side){width:340px;flex:none;height:100%;overflow-y:auto;overflow-x:hidden;background:var(--sheet);border-right:1px solid var(--rule);
  scrollbar-width:thin;scrollbar-color:#2c3239 transparent}
:where(.wtyg-map-reproduction_capture) :is([data-wtyg-id="side"],#wtyg-noid-side)::-webkit-scrollbar{width:6px}
:where(.wtyg-map-reproduction_capture) :is([data-wtyg-id="side"],#wtyg-noid-side)::-webkit-scrollbar-thumb{background:#2c3239;border-radius:3px}
:where(.wtyg-map-reproduction_capture) .blk{padding:16px 18px;border-bottom:1px solid var(--rule2)}
:where(.wtyg-map-reproduction_capture) .over{font-family:"IBM Plex Sans Condensed","IBM Plex Sans",sans-serif;font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:var(--faint)}
:where(.wtyg-map-reproduction_capture) h1{font-size:21px;font-weight:600;letter-spacing:-.01em;margin:4px 0 6px}
:where(.wtyg-map-reproduction_capture) .lead{color:#c3c0ba;font-size:13px}
:where(.wtyg-map-reproduction_capture) .un-line{color:var(--dim);font-size:12px;margin-top:8px}
:where(.wtyg-map-reproduction_capture) .un-line a,:where(.wtyg-map-reproduction_capture) .rc-src a{color:var(--accent);text-decoration:none}
:where(.wtyg-map-reproduction_capture) .un-line a:hover,:where(.wtyg-map-reproduction_capture) .rc-src a:hover{text-decoration:underline}
:where(.wtyg-map-reproduction_capture) .sec{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:8px}
:where(.wtyg-map-reproduction_capture) .lyr{display:grid;grid-template-columns:28px 1fr auto;column-gap:10px;align-items:start;padding:8px 0;cursor:pointer;user-select:none}
:where(.wtyg-map-reproduction_capture) .lyr+.lyr,:where(.wtyg-map-reproduction_capture) :is([data-wtyg-id="unopts"],#wtyg-noid-unopts)+.lyr{border-top:1px solid var(--rule2)}
:where(.wtyg-map-reproduction_capture) .sw{position:relative;width:28px;height:16px;margin-top:2px;border-radius:8px;background:#2a3037;transition:background .15s}
:where(.wtyg-map-reproduction_capture) .sw::after{content:"";position:absolute;top:2px;left:2px;width:12px;height:12px;border-radius:50%;background:#7d858d;transition:transform .15s,background .15s}
:where(.wtyg-map-reproduction_capture) .lyr.on .sw{background:var(--c)}
:where(.wtyg-map-reproduction_capture) .lyr.on .sw::after{transform:translateX(12px);background:#f2f0ec}
:where(.wtyg-map-reproduction_capture) .lyr input{position:absolute;opacity:0;pointer-events:none}
:where(.wtyg-map-reproduction_capture) .lyr .t{font-weight:500;font-size:13.5px;line-height:1.3}
:where(.wtyg-map-reproduction_capture) .lyr .d{display:block;font-size:12px;color:var(--faint);line-height:1.35;margin-top:1px}
:where(.wtyg-map-reproduction_capture) .lyr .n{font-size:12px;color:var(--faint);font-variant-numeric:tabular-nums;padding-top:1px}
:where(.wtyg-map-reproduction_capture) .lyr:not(.on) .t{color:var(--dim)}
:where(.wtyg-map-reproduction_capture) :is([data-wtyg-id="unopts"],#wtyg-noid-unopts){padding:2px 0 10px 38px}
:where(.wtyg-map-reproduction_capture) :is([data-wtyg-id="unopts"],#wtyg-noid-unopts) label{display:block;font-size:11.5px;color:var(--faint);margin-bottom:4px}
:where(.wtyg-map-reproduction_capture) select{width:100%;background:#101317;border:1px solid var(--rule);color:var(--text);border-radius:4px;padding:6px 8px;font:inherit;font-size:12.5px}
:where(.wtyg-map-reproduction_capture) select:focus,:where(.wtyg-map-reproduction_capture) input[type=search]:focus{outline:none;border-color:#3d4650}
:where(.wtyg-map-reproduction_capture) :is([data-wtyg-id="unleg"],#wtyg-noid-unleg){display:flex;flex-direction:column;gap:3px;margin-top:8px;font-size:12px;color:var(--dim)}
:where(.wtyg-map-reproduction_capture) :is([data-wtyg-id="unleg"],#wtyg-noid-unleg) span{display:flex;align-items:center;gap:7px}
:where(.wtyg-map-reproduction_capture) :is([data-wtyg-id="unleg"],#wtyg-noid-unleg) i{flex:none;width:11px;height:11px;border-radius:2px}
:where(.wtyg-map-reproduction_capture) :is([data-wtyg-id="unleg"],#wtyg-noid-unleg) em{font-style:normal;color:var(--faint);margin-left:auto;font-variant-numeric:tabular-nums}
:where(.wtyg-map-reproduction_capture) input[type=search]{width:100%;background:#101317;border:1px solid var(--rule);color:var(--text);border-radius:4px;padding:7px 9px;font:inherit;font-size:13px}
:where(.wtyg-map-reproduction_capture) :is([data-wtyg-id="count"],#wtyg-noid-count){font-size:11.5px;color:var(--faint);margin-top:6px}
:where(.wtyg-map-reproduction_capture) :is([data-wtyg-id="list"],#wtyg-noid-list){list-style:none}
:where(.wtyg-map-reproduction_capture) :is([data-wtyg-id="list"],#wtyg-noid-list) li{display:grid;grid-template-columns:8px 1fr;gap:10px;padding:8px 18px;border-bottom:1px solid var(--rule2);cursor:pointer}
:where(.wtyg-map-reproduction_capture) :is([data-wtyg-id="list"],#wtyg-noid-list) li:hover,:where(.wtyg-map-reproduction_capture) :is([data-wtyg-id="list"],#wtyg-noid-list) li:focus{background:var(--sheet2);outline:none}
:where(.wtyg-map-reproduction_capture) :is([data-wtyg-id="list"],#wtyg-noid-list) li .k{width:7px;height:7px;border-radius:50%;margin-top:6px}
:where(.wtyg-map-reproduction_capture) :is([data-wtyg-id="list"],#wtyg-noid-list) li .tt{font-size:13px;line-height:1.35}
:where(.wtyg-map-reproduction_capture) :is([data-wtyg-id="list"],#wtyg-noid-list) li .m{font-size:11.5px;color:var(--faint);margin-top:1px}
:where(.wtyg-map-reproduction_capture) :is([data-wtyg-id="credit"],#wtyg-noid-credit){font-size:11px;color:var(--faint);padding:14px 18px 18px}
:where(.wtyg-map-reproduction_capture) :is([data-wtyg-id="map"],#wtyg-noid-map){flex:1;min-width:0;height:100%;background:#0b0d10}
:where(.wtyg-map-reproduction_capture) .leaflet-container{font-family:inherit;background:#0b0d10;outline:none}
:where(.wtyg-map-reproduction_capture) .leaflet-interactive:focus{outline:none}
:where(.wtyg-map-reproduction_capture) .leaflet-bar{border:1px solid var(--rule)!important;box-shadow:none!important;border-radius:4px!important;overflow:hidden}
:where(.wtyg-map-reproduction_capture) .leaflet-bar a{background:rgba(20,23,27,.92)!important;color:var(--text)!important;border-bottom:1px solid var(--rule)!important;width:30px!important;height:30px!important;line-height:30px!important;font-weight:400}
:where(.wtyg-map-reproduction_capture) .leaflet-bar a:hover{background:#20252b!important}
:where(.wtyg-map-reproduction_capture) .leaflet-control-attribution{background:rgba(13,15,18,.72)!important;color:#7d858d!important;font-size:10.5px}
:where(.wtyg-map-reproduction_capture) .leaflet-control-attribution a{color:#9aa0a6!important}
:where(.wtyg-map-reproduction_capture) :is([data-wtyg-id="bases"],#wtyg-noid-bases){position:absolute;top:10px;right:10px;z-index:800;display:flex;background:rgba(20,23,27,.92);border:1px solid var(--rule);border-radius:4px;overflow:hidden}
:where(.wtyg-map-reproduction_capture) :is([data-wtyg-id="bases"],#wtyg-noid-bases) button{background:none;border:0;border-right:1px solid var(--rule);color:var(--dim);font:inherit;font-size:12px;padding:6px 11px;cursor:pointer}
:where(.wtyg-map-reproduction_capture) :is([data-wtyg-id="bases"],#wtyg-noid-bases) button:last-child{border-right:0}
:where(.wtyg-map-reproduction_capture) :is([data-wtyg-id="bases"],#wtyg-noid-bases) button:hover{color:var(--text)}
:where(.wtyg-map-reproduction_capture) :is([data-wtyg-id="bases"],#wtyg-noid-bases) button[aria-pressed=true]{background:#262c33;color:var(--text)}
:where(.wtyg-map-reproduction_capture) .leaflet-popup-content-wrapper{background:#15181c;color:var(--text);border:1px solid var(--rule);border-radius:4px;box-shadow:0 10px 30px rgba(0,0,0,.5)}
:where(.wtyg-map-reproduction_capture) .leaflet-popup-tip{background:#15181c;border:1px solid var(--rule);box-shadow:none}
:where(.wtyg-map-reproduction_capture) .leaflet-popup-content{margin:14px 16px 12px;width:360px;max-width:100%}
:where(.wtyg-map-reproduction_capture) .leaflet-container a.leaflet-popup-close-button{color:var(--faint);top:6px;right:6px}
:where(.wtyg-map-reproduction_capture) .leaflet-tooltip{background:#15181c;color:var(--text);border:1px solid var(--rule);border-radius:3px;box-shadow:none;font-size:12px;padding:3px 7px}
:where(.wtyg-map-reproduction_capture) .leaflet-tooltip:before{display:none}
:where(.wtyg-map-reproduction_capture) .rc-box{font-size:13px;line-height:1.5}
:where(.wtyg-map-reproduction_capture) .rc-kind{font-family:"IBM Plex Sans Condensed","IBM Plex Sans",sans-serif;font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:var(--faint);display:flex;align-items:center;gap:7px}
:where(.wtyg-map-reproduction_capture) .rc-kind i{width:8px;height:8px;border-radius:50%;display:inline-block}
:where(.wtyg-map-reproduction_capture) .rc-box h3{font-weight:600;font-size:16px;line-height:1.3;margin:6px 0 3px;color:var(--text)}
:where(.wtyg-map-reproduction_capture) .rc-meta{font-size:12px;color:var(--dim)}
:where(.wtyg-map-reproduction_capture) .rc-what{margin:9px 0 8px;color:#d9d6d0}
:where(.wtyg-map-reproduction_capture) .rc-box dl{display:grid;grid-template-columns:96px 1fr;gap:5px 12px;font-size:12.5px;border-top:1px solid var(--rule);padding-top:8px}
:where(.wtyg-map-reproduction_capture) .rc-box dt{color:var(--faint)}
:where(.wtyg-map-reproduction_capture) .rc-box dd{color:#cfccc6}
:where(.wtyg-map-reproduction_capture) .rc-src{margin-top:9px;border-top:1px solid var(--rule);padding-top:7px;font-size:12px;color:var(--faint)}
:where(.wtyg-map-reproduction_capture) .rc-src b{font-weight:500;color:var(--dim)}
:where(.wtyg-map-reproduction_capture) .rc-src ol{margin:3px 0 4px 18px}
:where(.wtyg-map-reproduction_capture) .rc-pt{margin-top:7px;font-size:11px;color:var(--faint)}
:where(.wtyg-map-reproduction_capture) .rc-un{margin-top:8px;padding:8px 10px;border-radius:3px;background:#1c2025;font-size:12.5px}
:where(.wtyg-map-reproduction_capture) .rc-sec{margin-top:8px;border-top:1px solid var(--rule);padding-top:6px}
:where(.wtyg-map-reproduction_capture) .rc-sec summary{cursor:pointer;font-family:"IBM Plex Sans Condensed","IBM Plex Sans",sans-serif;font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:var(--dim)}
:where(.wtyg-map-reproduction_capture) .rc-box .rc-sec dl{grid-template-columns:1fr minmax(84px,40%);border-top:0;padding-top:6px}
:where(.wtyg-map-reproduction_capture) .rc-box .rc-sec dd{text-align:right}
:where(.wtyg-map-reproduction_capture) .rc-qh{grid-column:1/-1;color:var(--faint);font-size:12px;padding-top:7px;border-top:1px dashed var(--rule)}
:where(.wtyg-map-reproduction_capture) .rc-note{display:block;color:var(--faint);font-size:11px;margin-top:2px;text-align:left}
@media (max-width:760px){:where(.wtyg-map-reproduction_capture) :is([data-wtyg-id="rc"],#wtyg-noid-rc){flex-direction:column-reverse}
:where(.wtyg-map-reproduction_capture) :is([data-wtyg-id="side"],#wtyg-noid-side){width:100%;height:45%;border-right:0;border-top:1px solid var(--rule)}
:where(.wtyg-map-reproduction_capture) :is([data-wtyg-id="map"],#wtyg-noid-map){height:55%;flex:none}
:where(.wtyg-map-reproduction_capture) .leaflet-popup-content{width:270px}
:where(.wtyg-map-reproduction_capture) .rc-box dl{grid-template-columns:78px 1fr}
:where(.wtyg-map-reproduction_capture) :is([data-wtyg-id="bases"],#wtyg-noid-bases) button{padding:5px 8px;font-size:11px}}
